import csv
import io
import re
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        strict=False,
    )
    records = list(reader)

    header_index = None
    columns = None
    for index, record in enumerate(records):
        if (
            len(record) >= 3
            and record[0].strip() == "Country"
            and record[1].strip() == "Age or Life Stage Group"
            and record[2].strip() == "Sex"
        ):
            header_index = index
            columns = record
            break

    if header_index is None or columns is None:
        return {"columns": [], "rows": []}

    width = len(columns)
    rows = []

    for record in records[header_index + 1:]:
        if not record or not any(value.strip() for value in record):
            continue

        first = record[0].strip()
        if re.match(r"^(?:Data\s+source\s*:|See\b|[EF]\s{1,})", first, re.IGNORECASE):
            break

        if len(record) < width:
            record = record + [""] * (width - len(record))
        elif len(record) > width:
            record = record[:width - 1] + [",".join(record[width - 1:])]

        rows.append(record)

    return {"columns": columns, "rows": rows}
